  return <svg width={size} height={size} viewBox=\"0 0 24 24\" fill={filled ? 'currentColor' : 'none'} stroke=\"currentColor\" strokeWidth=\"1.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\">{paths[name]}</svg>;
}

type Article = {id: number; title: string; category: string; minutes: number; image: string; description: string; body: string[]};
const articles: Article[] = [
  {id: 1, title: 'Искусство замедляться', category: 'Образ жизни', minutes: 8, image: 'forest', description: 'Как находить спокойствие в повседневности и замечать то, что действительно важно.', body: ['Иногда лучший способ двигаться вперёд — ненадолго остановиться. Прислушаться к шуму деревьев, почувствовать тепло чашки в ладонях, заметить, как свет меняется на стене. Эти маленькие моменты возвращают нас в настоящее.', 'Медленная жизнь не требует переезда за город или отказа от амбиций. Она начинается с простого вопроса: что заслуживает моего внимания прямо сейчас? Когда мы выбираем одно дело и отдаём ему всё внимание, даже обычное утро становится немного другим.', 'Попробуйте оставить первые десять минут дня свободными от экрана. Откройте окно, приготовьте любимый напиток, запишите одну мысль. Не стремитесь сделать из этого идеальный ритуал — просто дайте себе немного пространства.', 'Прогулка без маршрута, обед без спешки, разговор без поглядывания на часы. Спокойствие складывается из небольших решений. Не обязательно менять всё сразу: достаточно выбрать одно из них сегодня.']},
  {id: 2, title: 'Книги, к которым хочется возвращаться', category: 'Культура', minutes: 6, image: 'library', description: 'Истории, которые становятся нашими тихими собеседниками.', body: ['На каждой книжной полке есть особенные книги. Их корешки чуть потёрты, на полях остаются пометки, а между страницами можно найти билет из давней поездки. Мы возвращаемся к ним не только ради сюжета.', 'При повторном чтении знакомая история звучит иначе. Меняемся мы сами, и вместе с нами меняется то, что мы замечаем в тексте. Второстепенный герой вдруг становится ближе, а пропущенная когда-то фраза оказывается самой важной.', 'Выберите книгу, которую любили несколько лет назад. Откройте её на любой странице. Иногда для встречи с собой достаточно нескольких знакомых строк.']},
  {id: 3, title: 'Меньше вещей — больше пространства', category: 'Дизайн', minutes: 5, image: 'interior', description: 'Простой подход к дому, в котором легко дышать и приятно жить.', body: ['Уют измеряется не количеством предметов. Иногда именно свободный угол, солнечное пятно на полу и удобное кресло делают комнату любимым местом в доме.', 'Начните с одной поверхности: рабочего стола, подоконника или прикроватной тумбы. Уберите всё, а затем верните только то, чем пользуетесь или что радует вас. У каждой оставшейся вещи появится пространство.', 'Материалы тоже влияют на ощущение дома. Дерево, лён и керамика красиво стареют и делают повседневные прикосновения приятнее. Не торопитесь покупать новое — присмотритесь к тому, что у вас уже есть.']},
  {id: 4, title: 'Туда, где нет связи', category: 'Путешествия', minutes: 7, image: 'mountain', description: 'Небольшое путешествие навстречу большим горам и самому себе.', body: ['Горы меняют чувство времени. Здесь расстояние измеряется шагами, день — положением солнца, а хорошая новость — ясным небом над перевалом. Телефон постепенно перестаёт быть центром внимания.', 'Для первого путешествия не нужен сложный маршрут. Выберите знакомую тропу, проверьте погоду, возьмите воду и сообщите близким, куда идёте. Оставьте достаточно времени, чтобы останавливаться и смотреть вокруг.', 'Самое ценное часто происходит по пути: разговор у костра, вкус простого завтрака, тишина перед рассветом. Именно эти моменты мы увозим с собой, даже если не сделали ни одной фотографии.']},
];
const categories = ['Всё', 'Образ жизни', 'Культура', 'Дизайн', 'Путешествия'];
type Page = 'overview' | 'library' | 'favorites';
