function readStored<T,>(key: string, fallback: T): T {try { const item = localStorage.getItem(key); return item ? JSON.parse(item) : fallback; } catch {return fallback;}}
function getPage(): Page {const hash = window.location.hash.slice(1); return hash === 'library' || hash === 'favorites' ? hash : 'overview';}

