type IconName = 'home' | 'book' | 'bookmark' | 'sun' | 'moon' | 'search' | 'arrow' | 'arrow-up' | 'close' | 'clock' | 'leaf' | 'grid' | 'check';
function Icon({name, size = 20, filled = false}: {name: IconName; size?: number; filled?: boolean}) {
