@import url('https://fonts.googleapis.com/css2?family=Golos+Text:wght@400;450;500;550;600;650;700&family=Manrope:wght@500;600;700;800&display=swap');

:root{font-family:'Golos Text',sans-serif;color:#303a32;background:#fafbf8;font-synthesis:none;--page:#fafbf8;--sidebar:#f1f3ec;--panel:#fff;--ink:#303a32;--muted:#8a9087;--secondary:#747d72;--line:#e5e8df;--green:#4c6645;--soft:#e5ebdc;--hero:#eaf0e2;--filter:#f0f2eb;--card:#fff;--shadow:0 5px 20px #29342405}
:root[data-theme=dark]{color-scheme:dark;--page:#1c221e;--sidebar:#181e1a;--panel:#252d27;--ink:#e4e8df;--muted:#929d90;--secondary:#a3aea0;--line:#343e34;--green:#b3c8a0;--soft:#35432e;--hero:#2b3628;--filter:#293128;--card:#232b25;--shadow:0 5px 20px #00000010}
