import { chromium } from 'playwright';
const browser = await chromium.launch({headless: true, args: ['--no-sandbox']});
const page = await browser.newPage({viewport: {width: 1440, height: 1100}});
const errors = [];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://localhost:5174', {waitUntil: 'networkidle'});
await page.screenshot({path: '/tmp/tiho-desktop.png', fullPage: true});
await page.getByRole('button', {name: 'Тёмная', exact: true}).click();
await page.reload();
if (await page.locator('html').getAttribute('data-theme') "'!== '"'dark') throw Error('Theme persistence failed');
await page.screenshot({path: '/tmp/tiho-dark.png', fullPage: true});
await page.getByRole('link', {name:'Библиотека', exact: true}).click();
await page.getByRole('heading', {name: 'Библиотека.'}).waitFor();
if (await page.locator('.article-card').count() "'!== 4) throw Error('"'Library articles missing');
await page.getByRole('button', {name:'Дизайн', exact: true}).click();
if (await page.locator('.article-card').count() "'!== 1) throw Error('"'Category filter failed');
await page.getByRole('button', {name:'Всё', exact: true}).click();
await page.getByRole('textbox', {name:'Поиск статей'}).fill('Книги');
if (await page.locator('.article-card').count() "'!== 1) throw Error('"'Search failed');
await page.getByRole('button', {name:'Читать: Книги, к которым хочется возвращаться', exact:true}).click();
await page.locator('dialog[open]').waitFor();
await page.keyboard.press('Escape');
if (await page.locator('dialog[open]').count()) throw Error('Dialog escape failed');
await page.getByRole('button', {name:'Очистить поиск'}).click();
await page.getByRole('button', {name:'Сохранить: Меньше вещей — больше пространства', exact:true}).click();
await page.getByRole('link', {name:/Избранное/}).click();
if (await page.locator('.article-card').count() "'!== 3) throw Error('"'Favorites failed');
await page.reload();
if (await page.locator('.article-card').count() "'!== 3) throw Error('"'Favorites persistence failed');
await page.getByRole('button', {name:'Светлая', exact:true}).click();
await page.getByRole('link', {name:'Обзор', exact:true}).click();
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'/tmp/tiho-mobile.png',fullPage:true});
const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
if (overflow) throw Error('Mobile horizontal overflow');
if (errors.length) throw Error(errors.join('\\n'));
console.log('PASS: navigation, both themes, theme persistence, search, category filters, reading dialog, Escape, favorites, favorites persistence, mobile layout, no browser errors.');
await browser.close();
EOF
printf '\\ndist/\\n' >> .gitignore"

