let css=await fs.readFile('src/styles.css','utf8');css=css.slice(css.indexOf('\\n'));css='@import url(\"/fonts/fonts.css\");\\n'+css;css=css.replaceAll('\"Lora\", \"Lora\", Georgia, serif','\"Lora\", Georgia, serif');await fs.writeFile('src/styles.css',css);
EOF"
